#include <bits/stdc++.h>
using namespace std;

int maxPower, base;
unordered_set<long long> powersSet;

void generatePowers(int index, long long sum, int maxExp) {
    if (index > maxExp) {
        powersSet.insert(sum);
        return;
    }
    generatePowers(index + 1, sum + (long long)pow(base, index), maxExp);
    generatePowers(index + 1, sum, maxExp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int b;
    long long target;
    cin >> b >> target;
    base = b;

    int maxExponent = 0;
    for (int i = 0; i < 21; i++) {
        if (base > 2 && pow(base, i) > 1e9) {
            break;
        }
        maxExponent = i;
    }

    if (base > 2) generatePowers(0, 0, maxExponent);

    bool found = false;
    if (base == 2) found = true;

    for (auto val : powersSet) {
        if (val >= target && powersSet.count(val - target)) {
            found = true;
            break;
        }
    }

    cout << (found ? "YES" : "NO") << "\n";

    return 0;
}
